method add_elements(arr: array<int>, k: int) returns (sum: int)
    requires arr != null && |arr| > 0 && |arr| <= 100
    requires 1 <= k <= |arr|
    ensures sum == SumOfTwoDigitElements(arr, k)

    // Helper function to calculate the sum of two-digit elements
    function SumOfTwoDigitElements(arr: array<int>, k: int): int
        reads arr
        requires arr != null && |arr| > 0 && |arr| <= 100
        requires 1 <= k <= |arr|
    {
        var total := 0;
        var count := 0;
        var i := 0;
        while (i < k)
            invariant 0 <= i <= k
            invariant total == SumOfTwoDigitElements(arr, i)
            invariant count == CountTwoDigitElements(arr, i)
        {
            if (arr[i] >= -99 && arr[i] <= 99) {
                total := total + arr[i];
                count := count + 1;
            }
            i := i + 1;
        }
        total;
    }

    // Count two-digit elements in the array up to index k
    function CountTwoDigitElements(arr: array<int>, k: int): int
        reads arr
        requires arr != null && |arr| > 0 && |arr| <= 100
        requires 1 <= k <= |arr|
    {
        var count := 0;
        for i := 0 to k - 1
            if (arr[i] >= -99 && arr[i] <= 99) {
                count := count + 1;
            }
        count;
    }
